SELECT Имена_станций.NAME, Конфигурации.NGT, GTD.Model AS ГТУ, Конфигурации.NKU, [Котлы-утилизаторы].Model AS Котел, Конфигурации.NPT, [Паровые турбины].Model AS ПТ, [Станция-конфигурация].stan
FROM (((([Станция-конфигурация] INNER JOIN Конфигурации ON [Станция-конфигурация].conf=Конфигурации.conf) INNER JOIN Имена_станций ON [Станция-конфигурация].stan=Имена_станций.NUMB) INNER JOIN GTD ON Конфигурации.GT=GTD.cmodel) LEFT JOIN [Котлы-утилизаторы] ON Конфигурации.KU=[Котлы-утилизаторы].cmodel) LEFT JOIN [Паровые турбины] ON Конфигурации.PT=[Паровые турбины].cmodel
ORDER BY Имена_станций.ordnumb;
